mapper.select:
SELECT

    (
        SELECT COUNT(*)
        FROM employee
        WHERE merchant_id = #{merchantId}
    ) AS employeeCount,

    (
        SELECT COUNT(*)
        FROM user
    ) AS userCount,

    (
        SELECT COUNT(*)
        FROM category
        WHERE merchant_id = #{merchantId}
    ) AS categoryCount,

    (
        SELECT COUNT(*)
        FROM dish
        WHERE merchant_id = #{merchantId}
    ) AS dishCount,

    (
        SELECT COUNT(*)
        FROM orders
        WHERE merchant_id = #{merchantId}
          AND status = 1
    ) AS pendingOrderCount,

    (
        SELECT COUNT(*)
        FROM orders
        WHERE merchant_id = #{merchantId}
          AND status = 2
    ) AS paidOrderCount,

    (
        SELECT COUNT(*)
        FROM orders
        WHERE merchant_id = #{merchantId}
          AND status = 3
    ) AS completedOrderCount,

    (
        SELECT COUNT(*)
        FROM orders
        WHERE merchant_id = #{merchantId}
          AND status = 4
    ) AS cancelledOrderCount
